<script lang="ts">
 import {onMount} from 'svelte';
 import Icon from '@us/ui/Icon.svelte';
 import PhotoSetup from '@us/ui/PhotoSetup.svelte';
 import {reviewBridge,reviewPair} from '@us/ui/review-bridge';
 import type {Job,Reference} from '@us/shared/types';
 let bridge=reviewBridge();let composer='';let reply:Reference|undefined;let setupOpen=false;let photoMode=false;
 let status='';let job:Job|undefined;let sent:Job[]=[];let busy=false;let pending='';let input:HTMLInputElement;
 onMount(()=>{const timer=setInterval(async()=>{if(job?.status!=='generating')return;const next=(await bridge.listJobs()).find(j=>j.id===job?.id);if(next?.status==='ready'){sent=[...sent,{...next,status:'sent'}];job=undefined;status='';}else if(next)job=next},500);return()=>clearInterval(timer)});
 function shortcut(kind:'reel'|'video'){reply={kind,mediaId:'preview',url:'/fixture.mp4'};composer=kind==='reel'?'/us Make this us':'/us What happens next?';input?.focus()}
 async function submit(){
  if(busy||job?.status==='generating')return;
  if(!/^\/us(?:\s|$)/i.test(composer.trim())){status='Try /us followed by an idea.';return;}
  const text=composer.trim().slice(3).trim();
  if(text==='settings'){composer='';setupOpen=true;photoMode=false;return;}
  if(!text&&!reply){status='Add an idea after /us.';return;}
  pending=text||'Personalize this scene for us.';composer='';
  const setup=await bridge.getSetup();if(!setup.photoConfirmed){setupOpen=true;photoMode=true;return;}
  await generate();
 }
 async function generate(){if(!pending||busy)return;busy=true;try{status='Creating your video…';job=await bridge.createJob({...reviewPair,instruction:pending,reference:reply,idempotencyKey:crypto.randomUUID()});pending='';reply=undefined;}finally{busy=false}}
 async function confirmed(){setupOpen=false;if(pending)await generate();}
</script>
<svelte:head><title>Us — Instagram flow preview</title><meta name="description" content="Local, fixture-only preview of the Us Instagram extension."/></svelte:head>
<div class="app">
 <aside class="rail"><span class="instagram">◎</span><Icon name="home" size={26}/><Icon name="search" size={26}/><Icon name="reel" size={26}/><Icon name="chat" size={26}/><Icon name="heart" size={26}/><Icon name="plus" size={26}/></aside>
 <aside class="inbox"><h1>{reviewPair.sender.username} <span>⌄</span></h1><div class="inbox-heading"><b>Messages</b><span>Requests</span></div><div class="selected-chat"><div class="avatar">{reviewPair.recipient.name[0]}</div><div><b>{reviewPair.recipient.name}</b><small>You shared a reel. · 2m</small></div></div></aside>
 <main>
  <header class="chat-header"><div class="avatar small">{reviewPair.recipient.name[0]}</div><div class="person"><b>{reviewPair.recipient.name}</b><span>{reviewPair.recipient.username}</span></div><div class="header-actions"><Icon name="phone" size={24}/><Icon name="video" size={25}/><Icon name="info" size={24}/></div></header>
  <div class="conversation"><div class="profile"><div class="avatar large">{reviewPair.recipient.name[0]}</div><h2>{reviewPair.recipient.name}</h2><p>{reviewPair.recipient.username} · Instagram</p></div><div class="date">TODAY 9:41 PM</div><div class="bubble theirs">okay but imagine us here</div>
   <div class="shared-reel"><div class="scene"><Icon name="reel" size={22}/><span>somewhere, together</span></div><button class="shortcut" onclick={()=>shortcut('reel')}>Make this us</button></div>
   <div class="bubble mine">this is so us 😭</div>
   {#if job?.status==='generating'}<div class="generating-reel" role="status"><span class="spinner" aria-hidden="true"></span><span>Generating…</span></div>{/if}
   {#each sent as video}<div class="sent-video"><video src={video.outputUrl} controls playsinline preload="metadata"><track kind="captions"/></video><small>Prerecorded demo · not AI generated</small><button class="shortcut" onclick={()=>shortcut('video')}>Continue</button></div>{/each}
  </div>
  <div class="composer-wrap">
   {#if status&&!job}<div class="status" role="status">{status}</div>{/if}
   {#if reply}<div class="native-reply"><div><small>Replying to {reviewPair.recipient.name}</small><span>{reply.kind==='reel'?'Reel':'Video'}</span></div><button aria-label="Cancel reply" onclick={()=>reply=undefined}>×</button></div>{/if}
   <form class="composer" onsubmit={event=>{event.preventDefault();submit()}}><Icon name="smile" size={24}/><input bind:this={input} aria-label="Instagram message" bind:value={composer} placeholder="Message…"/>{#if composer}<button class="send" type="submit" aria-label="Send"><Icon name="send" size={22}/></button>{:else}<span class="composer-icons"><Icon name="mic" size={23}/><Icon name="image" size={24}/><Icon name="heart" size={24}/></span>{/if}</form>
  </div>
 </main>
</div>
<div class="preview-bar"><span>Local preview · prerecorded videos · nothing is sent</span><div><button onclick={()=>{reply=undefined;composer='/us ';input?.focus()}}>Text</button><button onclick={()=>shortcut('reel')}>Reel</button><button onclick={()=>shortcut('video')}>Reply</button><button onclick={()=>{bridge=reviewBridge(false);photoMode=true;setupOpen=true}}>Photo setup</button><button onclick={()=>{photoMode=false;setupOpen=true}}>Settings</button></div></div>
{#if setupOpen}<PhotoSetup {bridge} pair={reviewPair} settings={!photoMode} onclose={()=>setupOpen=false} onconfirmed={confirmed}/>{/if}
<style>
 :global(body){margin:0;background:#fff;color:#262626;font:14px/1.4 -apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif}:global(*){box-sizing:border-box}:global(button){font:inherit;cursor:pointer}:global(button:focus-visible){outline:2px solid #4a5df9;outline-offset:3px}.app{height:calc(100dvh - 44px);min-height:550px;display:flex}.rail{width:76px;flex-shrink:0;border-right:1px solid #dbdbdb;display:flex;align-items:center;flex-direction:column;padding:28px 0;gap:34px}.instagram{font-size:37px;margin-bottom:20px}.inbox{width:310px;flex-shrink:0;border-right:1px solid #dbdbdb}.inbox h1{font-size:20px;padding:30px 24px;margin:0}.inbox h1 span{font-size:15px;margin-left:8px}.inbox-heading{display:flex;justify-content:space-between;padding:20px 24px}.inbox-heading span{color:#737373;font-size:13px}.selected-chat{padding:18px 24px;display:flex;align-items:center;gap:12px;background:#f4f4f4}.selected-chat b{font-size:14px;font-weight:500}.selected-chat small{display:block;font-size:12px;color:#737373;margin-top:5px}.avatar{width:50px;height:50px;border-radius:50%;background:#e1e5df;color:#53604f;display:grid;place-items:center;font-size:22px;flex-shrink:0}.small{width:42px;height:42px;font-size:18px}.large{width:70px;height:70px;margin:0 auto 12px;font-size:28px}main{position:relative;flex:1;min-width:0;display:flex;flex-direction:column}.chat-header{height:86px;display:flex;align-items:center;border-bottom:1px solid #dbdbdb;padding:0 28px;gap:13px;flex-shrink:0}.person b{display:block;font-size:16px}.person span{display:block;color:#737373;font-size:12px;margin-top:4px}.header-actions{margin-left:auto;display:flex;gap:22px}.conversation{flex:1;overflow:auto;display:flex;flex-direction:column;align-items:flex-start;padding:25px 30px 18px;gap:8px}.profile{align-self:center;text-align:center;margin:0 0 16px}.profile h2{font-size:18px;margin:0 0 6px}.profile p{font-size:12px;color:#737373;margin:0}.date{align-self:center;color:#8e8e8e;font-size:10px;margin:5px 0 20px}.bubble{border-radius:18px;padding:11px 16px;font-size:14px}.theirs{background:#efefef;border-bottom-left-radius:5px}.mine{align-self:flex-end;background:#4a5df9;color:#fff;border-bottom-right-radius:5px;margin-top:12px}.shared-reel{width:210px}.scene{height:220px;background:linear-gradient(170deg,#b9c6b9,#657b65);color:white;display:flex;flex-direction:column;justify-content:space-between;padding:16px;border-radius:12px}.scene span{font-size:18px}.shortcut{display:block;border:0;background:none;color:inherit;padding:8px 2px 0;font-size:12px;font-weight:600}.generating-reel{align-self:flex-end;width:200px;aspect-ratio:9/16;flex-shrink:0;border-radius:16px;background:#262626;color:white;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;margin-top:8px;font-weight:500}.spinner{width:25px;height:25px;border:2px solid #ffffff40;border-top-color:white;border-radius:50%;animation:generating 1s linear infinite}@keyframes generating{to{transform:rotate(360deg)}}@media(prefers-reduced-motion:reduce){.spinner{animation:none}}.sent-video{align-self:flex-end;width:236px;margin-top:12px}.sent-video video{width:100%;display:block;border-radius:12px;background:#eee}.sent-video small{display:block;font-size:10px;color:#737373;margin-top:6px}.sent-video .shortcut{margin-left:auto}.composer-wrap{position:relative;padding:18px 24px 22px;flex-shrink:0}.composer{height:54px;border:1px solid #dbdbdb;border-radius:28px;padding:11px 17px;display:flex;align-items:center;gap:14px}.composer input{flex:1;min-width:0;border:0;outline:0;font:inherit;background:none;color:inherit}.composer-icons{display:flex;gap:17px}.send{border:0;background:#4a5df9;border-radius:20px;color:white;width:44px;height:32px;display:grid;place-items:center}.status{position:absolute;left:40px;bottom:calc(100% - 12px);font-size:12px;color:#737373}.native-reply{display:flex;justify-content:space-between;align-items:center;border-left:2px solid #dbdbdb;padding:8px 13px;margin:0 16px 10px}.native-reply small{display:block;color:#737373;font-size:12px}.native-reply span{font-size:13px}.native-reply button{border:0;background:none;color:#737373;font-size:24px}.preview-bar{height:44px;background:#fafafa;border-top:1px solid #dbdbdb;display:flex;align-items:center;justify-content:space-between;padding:0 18px;gap:12px;color:#737373;font-size:11px}.preview-bar>div{display:flex;gap:5px}.preview-bar button{background:none;border:0;font-size:11px;color:#737373;padding:6px 8px}@media(max-width:900px){.inbox{width:230px}.selected-chat{padding:15px}.inbox h1{padding:28px 18px}.inbox-heading{padding:18px}}@media(max-width:700px){.inbox{display:none}.rail{width:60px}.header-actions{gap:15px}.chat-header{padding:0 20px}}@media(max-width:480px){.rail{display:none}.chat-header{height:73px}.conversation{padding:20px}.composer-wrap{padding:18px 16px 22px}.preview-bar{padding:0 8px;font-size:9px;gap:4px}.preview-bar>span{max-width:110px}.preview-bar button{font-size:10px;padding:4px}.composer-icons{gap:12px}}
